define(["jquery"],function($){function isMobileViewport(){return window.matchMedia("(max-width: 991.98px)").matches}function syncButtons(shell,isOpen){shell.querySelectorAll("[data-kopere_dashboard-sidebar-open]").forEach(function(button){button.setAttribute("aria-expanded",isOpen?"true":"false")})}function closeSidebar(shell){shell.classList.remove("is-sidebar-open");document.body.classList.remove("has-kopere_dashboard-sidebar-open");syncButtons(shell,false)}function openSidebar(shell){shell.classList.add("is-sidebar-open");document.body.classList.add("has-kopere_dashboard-sidebar-open");syncButtons(shell,true)}var STORAGE_KEY="local_kopere_dashboard-submenus";var TRANSITION_MS=300;function submenuKey(summary){let link=summary.querySelector(".kopere_dashboard-card-navlink");return link?link.getAttribute("href"):null}function readState(){try{return JSON.parse(window.sessionStorage.getItem(STORAGE_KEY))||{}}catch(e){return{}}}function saveState(key,isExpanded){if(!key){return}try{let state=readState();state[key]=isExpanded;window.sessionStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(e){}}function expandSubmenu(summary,children,animate){summary.classList.add("is-expanded");children.classList.add("is-expanded");summary.setAttribute("aria-expanded","true");if(!animate){children.style.maxHeight="none";return}children.style.maxHeight=children.scrollHeight+"px";window.setTimeout(function(){if(children.classList.contains("is-expanded")){children.style.maxHeight="none"}},TRANSITION_MS)}function collapseSubmenu(summary,children,animate){summary.classList.remove("is-expanded");summary.setAttribute("aria-expanded","false");if(!animate){children.classList.remove("is-expanded");children.style.maxHeight="";return}children.style.maxHeight=children.scrollHeight+"px";window.requestAnimationFrame(function(){window.requestAnimationFrame(function(){children.classList.remove("is-expanded");children.style.maxHeight="0px"})})}function toggleSubmenu(summary){let children=summary.nextElementSibling;if(!children||!children.classList.contains("kopere_dashboard-card-navchildren")){return}let shouldExpand=!summary.classList.contains("is-expanded");if(shouldExpand){expandSubmenu(summary,children,true)}else{collapseSubmenu(summary,children,true)}saveState(submenuKey(summary),shouldExpand)}function bindSubmenus(shell){let state=readState();shell.querySelectorAll(".kopere_dashboard-card-navsummary").forEach(function(summary){let children=summary.nextElementSibling;if(!children||!children.classList.contains("kopere_dashboard-card-navchildren")){return}let key=submenuKey(summary);let stored=key&&Object.prototype.hasOwnProperty.call(state,key)?state[key]:null;let shouldExpand=stored===null?children.classList.contains("is-expanded"):stored;if(shouldExpand){expandSubmenu(summary,children,false)}else{collapseSubmenu(summary,children,false)}summary.addEventListener("click",function(event){if(event.target.closest(".kopere_dashboard-card-navlink")){return}event.preventDefault();toggleSubmenu(summary)})})}function bindShell(shell){if(!shell){return}let openButtons=shell.querySelectorAll("[data-kopere_dashboard-sidebar-open]");let closeButtons=shell.querySelectorAll("[data-kopere_dashboard-sidebar-close]");let backdrop=shell.querySelector("[data-kopere_dashboard-sidebar-backdrop]");bindSubmenus(shell);openButtons.forEach(function(button){button.addEventListener("click",function(){if(shell.classList.contains("is-sidebar-open")){closeSidebar(shell);return}openSidebar(shell)})});closeButtons.forEach(function(button){button.addEventListener("click",function(){closeSidebar(shell)})});if(backdrop){backdrop.addEventListener("click",function(){closeSidebar(shell)})}shell.querySelectorAll(".kopere_dashboard-card-sidenav a").forEach(function(link){link.addEventListener("click",function(){if(isMobileViewport()){closeSidebar(shell)}})});syncButtons(shell,false)}function init(){let shells=Array.prototype.slice.call(document.querySelectorAll("[data-kopere_dashboard-shell]"));if(!shells.length){return}shells.forEach(function(shell){bindShell(shell)});document.addEventListener("keydown",function(event){if(event.key!=="Escape"){return}shells.forEach(function(shell){closeSidebar(shell)})});$(window).on("resize",function(){if(isMobileViewport()){return}shells.forEach(function(shell){closeSidebar(shell)})})}return{init:init}});